import React from "react";
import _ from "lodash";

import "../assets/css/loading-page.css";

class LoadingPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = { width: window.outerWidth, height: window.outerHeight };
  }

  componentDidMount() {
    window.addEventListener("resize", () =>
      this.setState({ width: window.outerWidth, height: window.outerHeight })
    );
  }

  render() {
    const width = 40;

    const spacing = width + 10;
    const jumpHeight = 150;

    const numPoints = 15;

    const circleRingLeft = _.times(numPoints, n => {
      const x = n * spacing;

      return (
        <div
          className="circle"
          style={{
            offsetPath: `path("M ${x - (numPoints * spacing) / 2},${
              this.height / 2
            } l ${0},-${jumpHeight}")`,
            animationDelay: `-${0.1 * n}s`
          }}
        ></div>
      );
    });

    return <div className="loading-page-wrapper">{circleRingLeft}</div>;
  }
}

export default LoadingPage;
